import {vectorCheck} from './vector-check.mjs';
import {paymentConnections,checkoutTotals} from './payments.mjs';
import {session,getRule,quote,fileRow} from '../studio.mjs';
import {PRODUCTS,answers} from '../studio-model.mjs';
import {publicProducts} from '../catalog.mjs';
import {inspectPDF} from './preflight.mjs';
import {shippingRates} from './shipping.mjs';
const j=(v,s=200)=>new Response(JSON.stringify(v),{status:s,headers:{'Content-Type':'application/json','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}});
const clean=(v,n=200)=>typeof v==='string'?v.trim().slice(0,n):'';
const uuid=v=>/^[a-f0-9-]{36}$/i.test(v||'');
async function input(r){const text=await r.text();if(text.length>70000)throw Error('Request too large.');return JSON.parse(text);}
function specification(product,rule,values){const sizeField=rule.fields.find(f=>f.key==='size');const index=Math.max(0,sizeField?.options.findIndex(o=>o.value===values.size)||0);const size={...(product.sizes?.[index]||product.sizes?.[0]||{width:values.width||1,height:values.height||1})};if(rule.customSizeValue!==undefined&&rule.customSizeValue===values.size){size.width=values.width;size.height=values.height;}return {width:size.width,height:size.height,bleed:0.0625,sides:product.twoSided&&Number(values.print_sides)!==0?2:1};}
async function reports(item,s,env){const out=[];for(const id of item.fileIds){const row=await fileRow(env.DB,id,s.id,false);if(row.mime!=='application/pdf')throw Error('Print checkout requires a print-ready PDF. Replace image artwork with a PDF.');const object=await env.FILES.get(row.object_key);if(!object)throw Error('An artwork file is unavailable.');out.push({id,name:row.name,size:row.size,...await inspectPDF(new Uint8Array(await object.arrayBuffer()),item.spec)});}return out;}
function complete(item){return item.designRequested||item.artworkAccepted===true;}
export async function checkoutRoutes(request,env,url){if(!url.pathname.startsWith('/api/checkout/')&&url.pathname!=='/api/artwork/check')return null;
 if(!['GET','POST'].includes(request.method))return j({error:'Method not allowed'},405);
 if(request.method==='POST'&&request.headers.get('Origin')!==url.origin)return j({error:'Invalid request origin'},403);
 if(!env.DB||!env.FILES)return j({error:'Checkout is temporarily unavailable.'},503);
 try{const s=await session(request,env.DB);if(!s)return j({error:'Start a secure artwork session first.'},401);
 if(url.pathname==='/api/artwork/check'){const v=await input(request),rule=await getRule(env.DB,v.ruleId);if(!rule)throw Error('Product unavailable.');const values=answers(rule,v.values),product=PRODUCTS.find(p=>p.ruleId===rule.id)||{};if(!Array.isArray(v.fileIds)||v.fileIds.length>30)throw Error('Choose up to 30 files.');const item={fileIds:v.fileIds,spec:specification(product,rule,values)};const results=[];for(const id of v.fileIds){const file=await fileRow(env.DB,id,s.id,false);if(rule.id==='wrap-prints'){try{const object=await env.FILES.get(file.object_key);const dimensions=await vectorCheck(new Uint8Array(await object.arrayBuffer()),file.mime,values.width,values.height);results.push({id,name:file.name,status:'checked',message:'Vector file dimensions match the order at 1:1 scale. Cutting paths still require production review.',dimensions});}catch(e){results.push({id,name:file.name,status:'rejected',message:e.message});}continue;}if(file.mime==='application/pdf'){try{results.push(...await reports({...item,fileIds:[id]},s,env));}catch(e){results.push({id,name:file.name,status:'review',message:e.message});}}else results.push({id,name:file.name,status:'review',message:'Image/vector upload saved. Dimensions, resolution, colour and cutting paths require production review.'});}return j({reports:results});}
 const row=await env.DB.prepare('SELECT * FROM checkout_drafts WHERE session_id = ?').bind(s.id).first();let draft=row?JSON.parse(row.data):{items:[],address:null,rates:[],shipping:null,submitted:null},revision=row?.revision||0;
 const status=()=>({draft,revision,totals:checkoutTotals(draft,env),connections:{login:false,...paymentConnections(env),shipping:!!env.SHIPPO_API_KEY,preflight:false}});
 if(url.pathname==='/api/checkout/draft'&&request.method==='GET')return j(status());
 if(url.pathname==='/api/checkout/template'&&request.method==='GET'){const item=draft.items.find(i=>i.id===url.searchParams.get('item'));if(!item)throw Error('Item not found.');const product=(await publicProducts(env.DB)).find(p=>p.ruleId===item.ruleId);const esc=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));return new Response(`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PDF templates · Satin</title><style>body{font:16px system-ui;background:#f3f5f8;color:#172438;margin:0;padding:32px}main{max-width:650px;margin:auto;background:white;border-radius:16px;padding:32px}li{margin:16px 0}a{color:#b00040}</style><main><h1>${esc(item.name)} PDF templates</h1><p>Your ordered trim size: ${item.spec.width} × ${item.spec.height} in. Choose the matching size and finish below.</p>${product?.templates?.length?`<ul>${product.templates.map(t=>`<li><a href="${esc(t.url)}">${esc(t.label)}</a></li>`).join('')}</ul>`:'<p>No PDF template is currently available for this product.</p>'}<p><a href="/satin/checkout/">Return to checkout</a></p></main></html>`,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}}); }
 if(request.method!=='POST')return j({error:'Not found'},404);
 const v=await input(request);if(v.revision!==revision)return j({error:'Checkout changed. Reload before saving.'},409);if(draft.submitted&&url.pathname!=='/api/checkout/new')return j({error:'This request was already submitted. Start a new checkout.'},409);
 const path=url.pathname;let requestInsert=null;
 if(path==='/api/checkout/new'){draft={items:[],address:null,rates:[],shipping:null,submitted:null};
 }else if(path==='/api/checkout/import'){
  const templatesRow=await env.DB.prepare('SELECT value FROM site_settings WHERE key = ?').bind('vehicle_templates').first();const templates=templatesRow?JSON.parse(templatesRow.value):[];const catalog=await publicProducts(env.DB);const initialCount=draft.items.length;if(!Array.isArray(v.items)||v.items.length>30)throw Error('Import up to 30 items.');
  for(const a of v.items){const configured=catalog.find(p=>p.ruleId===a.pricing?.ruleId);if(!configured||!/(?:\/print-shop\/|\/wallpaper|\/window-graphics|\/apparel|\/shop\/)/.test(configured.path))continue;const product={...PRODUCTS.find(p=>p.ruleId===configured.ruleId),...configured};const key=clean(String(a.id),80);if(!key||draft.items.some(i=>i.sourceKey===key))continue;if(draft.items.length>=30)throw Error('Checkout contains the maximum 30 items.');const rule=await getRule(env.DB,product.ruleId),price=await quote(env.DB,rule.id,a.pricing.values,clean(a.pricing?.coupon,40));if(price.net<=0||(rule.customSizeValue!==undefined&&rule.customSizeValue===a.pricing.values?.size&&price.net<=(a.pricing.values?.design?Number(rule.constants.designFee||100)*100:0)))throw Error('Choose a standard size with an available print price.');const values=answers(rule,a.pricing.values);const fileIds=Array.isArray(a.artwork?.fileIds)?[...new Set(a.artwork.fileIds)].slice(0,30):a.artwork?.fileId?[a.artwork.fileId]:[];for(const id of fileIds){const f=await fileRow(env.DB,id,s.id,false);if(rule.id==='wrap-prints'){const object=await env.FILES.get(f.object_key);await vectorCheck(new Uint8Array(await object.arrayBuffer()),f.mime,values.width,values.height);}}let designFiles=[];if(a.artwork?.designId){const d=await env.DB.prepare('SELECT design FROM studio_designs WHERE id = ? AND session_id = ?').bind(a.artwork.designId,s.id).first();if(!d)throw Error('Design attachment unavailable.');const design=JSON.parse(d.design);if(!design.approvedAt)throw Error('Approve your design before checkout.');designFiles=(design.generated||[]).filter(f=>f.role==='artwork').map(f=>f.id);for(const id of designFiles)await fileRow(env.DB,id,s.id,false);}
   const item={id:crypto.randomUUID(),sourceKey:key,productId:product.id,name:product.name,path:product.path,ruleId:rule.id,values,coupon:clean(a.pricing?.coupon,40),price,spec:specification(product,rule,values),fileIds:fileIds.length?fileIds:designFiles,reports:[],artworkAccepted:product.artwork===false||a.artworkAccepted===true,proof:false,jobName:'',designRequested:rule.id==='design-services'||!!Number(values.design),choices:rule.fields.filter(f=>f.type==='select'&&!['quantity','print_sides','size'].includes(f.key)).map(f=>({label:f.label,text:f.options.find(o=>o.value===values[f.key])?.label||''}))};
   const template=templates.find(t=>t.ruleId===rule.id&&t.active);if(template){item.digitalKey=template.fileKey;item.digitalName=template.fileName;item.artworkAccepted=true;}else if(rule.id.startsWith('design-')&&rule.id!=='design-services'){const digital=await env.DB.prepare('SELECT * FROM digital_files WHERE rule_id = ? ORDER BY created_at DESC LIMIT 1').bind(rule.id).first();if(!digital)throw Error('This design file is not available for purchase yet. Request an exact quote.');item.digitalKey=digital.object_key;item.digitalName=digital.name;item.artworkAccepted=true;}
   if(fileIds.length)try{item.reports=await reports(item,s,env);}catch(e){item.artworkError=e.message;}draft.items.push(item);
  }if(draft.items.length===initialCount)return j(status());draft.rates=[];draft.shipping=null;
 }else if(path==='/api/checkout/item'){
  const item=draft.items.find(i=>i.id===v.id);if(!item)throw Error('Item not found.');
  if(v.remove===true){draft.items=draft.items.filter(i=>i.id!==v.id);draft.rates=[];draft.shipping=null;}
  else{if(v.fileIds!==undefined){if(!Array.isArray(v.fileIds)||v.fileIds.length>30||v.fileIds.some(id=>!uuid(id)))throw Error('Choose valid artwork files.');item.fileIds=[...new Set(v.fileIds)];item.proof=false;item.artworkError='';item.reports=[];try{item.reports=await reports(item,s,env);}catch(e){item.artworkError=e.message;}}
   if(v.proof===true){if(!item.fileIds.length)throw Error('Upload artwork first.');item.artworkAccepted=true;item.proof=true;item.proofAt=new Date().toISOString();}if(v.proof===false)item.proof=false;if(v.jobName!==undefined)item.jobName=clean(v.jobName,120);
  }
 }else if(path==='/api/checkout/shipping'){
  const a=v.address;if(!a||clean(a.name,120).length<2||!/^\S+@\S+\.\S+$/.test(clean(a.email,254))||!clean(a.street1)||!clean(a.city)||!/^[A-Z]\d[A-Z] ?\d[A-Z]\d$/i.test(a.zip||'')||!['ON','QC','BC','AB','MB','NB','NL','NS','NT','NU','PE','SK','YT'].includes(a.state)||a.country!=='CA')throw Error('Complete a valid Canadian delivery address.');
  draft.address=Object.fromEntries(['name','email','phone','company','street1','street2','city','state','zip','country'].map(k=>[k,clean(a[k],k==='email'?254:160)]));draft.address.zip=draft.address.zip.toUpperCase();const billing=v.billingAddress||a;if(!clean(billing.name)||!clean(billing.street1)||!clean(billing.city)||!/^\w\d\w ?\d\w\d$/i.test(billing.zip||''))throw Error('Complete your billing address.');draft.billingAddress=Object.fromEntries(['name','email','street1','street2','city','state','zip','country'].map(k=>[k,clean(billing[k],160)]));
  let packages={};try{packages=JSON.parse(env.SHIPPING_PACKAGES_JSON||'{}');}catch{}
  const parcels=draft.items.map(i=>packages[i.ruleId+':'+i.values.quantity]);const shipping=await shippingRates(draft.address,parcels.every(Boolean)?parcels:null,env);draft.rates=shipping.rates;draft.carrierStatus=shipping.carrierStatus;draft.shippingNotice=shipping.notice;draft.shipping=null;
 }else if(path==='/api/checkout/select-shipping'){
  const rate=draft.rates.find(r=>r.id===v.id);if(!rate)throw Error('Refresh and choose an available shipping method.');draft.shipping={...rate,selectedAt:new Date().toISOString()};
 }else if(path==='/api/checkout/request')return j({error:'Use the payment step to place your order.'},410);
 else return j({error:'Not found'},404);
 const encoded=JSON.stringify(draft);if(encoded.length>250000)throw Error('Checkout exceeds the allowed size.');const saveQuery=row?env.DB.prepare('UPDATE checkout_drafts SET data = ?,revision = revision + 1,updated_at = ? WHERE session_id = ? AND revision = ?').bind(encoded,new Date().toISOString(),s.id,revision):env.DB.prepare('INSERT INTO checkout_drafts (session_id,data,revision,updated_at) VALUES (?,?,1,?) ON CONFLICT(session_id) DO NOTHING').bind(s.id,encoded,new Date().toISOString());const saved=requestInsert?(await env.DB.batch([requestInsert,saveQuery]))[1]:await saveQuery.run();if(!saved.meta.changes)return j({error:'Checkout changed. Reload before saving.'},409);revision++;return j(status());
 }catch(e){console.error('Checkout failed',e?.message);return j({error:e?.message||'Checkout unavailable.'},400);}
}
